mapper.sql:
WITH input(base_date, base_time, nx, ny, category, obsr_value) AS ( VALUES
(CAST(#{item.baseDate} AS varchar), CAST(#{item.baseTime} AS varchar), CAST(#{item.nx} AS integer), CAST(#{item.ny} AS integer), CAST(#{item.category} AS varchar), CAST(#{item.obsrValue} AS numeric))
) INSERT INTO public.tb_ultra_srt_ncst (base_date, base_time, nx, ny, pty, reh, rn1, t1h, uuu, vec, vvv, wsd, c_date) SELECT base_date, base_time, nx, ny, MAX(obsr_value) FILTER (WHERE category = 'PTY')::smallint, MAX(obsr_value) FILTER (WHERE category = 'REH'), MAX(obsr_value) FILTER (WHERE category = 'RN1'), MAX(obsr_value) FILTER (WHERE category = 'T1H'), MAX(obsr_value) FILTER (WHERE category = 'UUU'), MAX(obsr_value) FILTER (WHERE category = 'VEC'), MAX(obsr_value) FILTER (WHERE category = 'VVV'), MAX(obsr_value) FILTER (WHERE category = 'WSD'), CURRENT_TIMESTAMP FROM input GROUP BY base_date, base_time, nx, ny
